package help.galaw.standalone

import android.app.AlertDialog
import android.content.Intent
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import org.json.JSONArray
import org.json.JSONObject
import kotlin.concurrent.thread

class HomeActivity : AppCompatActivity() {
    private lateinit var api: ApiClient
    private var onHome = true
    private var pendingUploadCaseId: Int? = null
    private val navy = Color.rgb(3, 17, 30)
    private val panel = Color.rgb(8, 31, 49)
    private val blue = Color.rgb(37, 168, 255)
    private val muted = Color.rgb(170, 190, 203)
    private val pickDocument = registerForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        val caseId = pendingUploadCaseId; pendingUploadCaseId = null
        if (uri == null || caseId == null) return@registerForActivityResult
        runTask("Uploading document…", { showCaseDocuments(caseId) }) { api.upload(caseId, uri); runOnUiThread { toast("Document uploaded securely."); showCaseDocuments(caseId) } }
    }
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); api = ApiClient(this); showHome() }
    @Deprecated("Deprecated in Java") override fun onBackPressed() { if (!onHome) showHome() else super.onBackPressed() }
    private fun dp(v: Int) = (v * resources.displayMetrics.density).toInt()
    private val homeActions = object : ApprovedHomeScreen.Actions {
        override fun openMenu()=showMenu(); override fun openAccount()=showAccount(); override fun ask(question:String)=askFromHome(question); override fun openCases()=showCases(); override fun openTalkToMe()=showTalkToMe(); override fun openLegalTools()=showLegalTools(); override fun openGeorgiaLaws()=showGeorgiaLaws(); override fun openCourtInfo()=showCourtInfo(); override fun openLegalForms()=showLegalForms(); override fun openCaseAnalysis()=showCaseAnalysis(); override fun openKnowYourRights()=showKnowYourRights(); override fun openResources()=showResources(); override fun openEmergency()=showEmergency(); override fun openHome()=showHome(); override fun openDocuments()=showDocuments()
    }
    private fun showHome(){ onHome=true; setContentView(ApprovedHomeScreen(this,homeActions).build()) }
    private fun page(title:String,subtitle:String?=null):LinearLayout{ onHome=false; val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(navy)}; val content=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(14),dp(16),dp(24))}; val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}; top.addView(TextView(this).apply{text="←";textSize=30f;setTextColor(Color.WHITE);gravity=Gravity.CENTER;contentDescription="Back to Home";setOnClickListener{showHome()}},LinearLayout.LayoutParams(dp(52),dp(48))); top.addView(TextView(this).apply{text="GA.LAW.HELP";textSize=20f;setTextColor(Color.WHITE);setTypeface(typeface,Typeface.BOLD)},LinearLayout.LayoutParams(0,-2,1f)); content.addView(top);content.addView(label(title,27f,true).apply{setPadding(0,dp(12),0,dp(3))});if(!subtitle.isNullOrBlank())content.addView(label(subtitle,13f).apply{setTextColor(muted);setPadding(0,0,0,dp(12))}); val scroll=ScrollView(this).apply{addView(content)};shell.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));shell.addView(bottomNav());setContentView(shell);return content }
    private fun bottomNav():View=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;setPadding(dp(3),dp(3),dp(3),dp(5));setBackgroundColor(Color.rgb(6,27,44));listOf(Triple("⌂","Home",{showHome()}),Triple("⚖","Laws",{showGeorgiaLaws()}),Triple("💬","AI Help",{showTalkToMe()}),Triple("📁","Documents",{showDocuments()}),Triple("●","Account",{showAccount()})).forEach{(icon,name,action)->addView(TextView(this@HomeActivity).apply{text="$icon\n$name";textSize=10f;gravity=Gravity.CENTER;setTextColor(Color.WHITE);setPadding(dp(2),dp(7),dp(2),dp(7));setOnClickListener{action()}},LinearLayout.LayoutParams(0,-2,1f))}}
    private fun label(value:String,size:Float=16f,bold:Boolean=false)=TextView(this).apply{text=value;textSize=size;setTextColor(Color.WHITE);setPadding(0,dp(7),0,dp(7));if(bold)setTypeface(typeface,Typeface.BOLD)}
    private fun input(hintText:String,multiLine:Boolean=false)=EditText(this).apply{hint=hintText;setHintTextColor(Color.rgb(145,167,185));setTextColor(Color.WHITE);setPadding(dp(16),dp(12),dp(16),dp(12));background=rounded(panel,blue,1,16);if(multiLine){minLines=4;gravity=Gravity.TOP}else setSingleLine(true)}
    private fun actionButton(title:String,action:()->Unit)=Button(this).apply{text=title;isAllCaps=false;textSize=15f;setTextColor(Color.WHITE);background=rounded(Color.rgb(10,39,62),Color.rgb(32,100,146),1,15);setOnClickListener{action()}}
    private fun addButton(root:LinearLayout,title:String,action:()->Unit){root.addView(actionButton(title,action),LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,dp(6),0,dp(6))})}
    private fun rounded(fill:Int,stroke:Int,width:Int,radius:Int)=GradientDrawable().apply{setColor(fill);cornerRadius=dp(radius).toFloat();if(width>0)setStroke(dp(width),stroke)}
    private fun requireSignedIn():Boolean{ if(api.token!=null)return true; toast("Sign in to use private case tools."); startActivity(Intent(this, AuthActivity::class.java)); return false }
    private fun showMenu(){AlertDialog.Builder(this).setTitle("GA.LAW.HELP").setItems(HomeDrawer.items.toTypedArray()){_,which->openDrawerItem(HomeDrawer.items[which])}.show()}
    private fun openDrawerItem(item:String){when(item){
        "Home"->showHome()
        "My Cases"->if(requireSignedIn())showCases()
        "AI Help"->showTalkToMe()
        "Legal Tools"->showLegalTools()
        "Georgia Laws"->showGeorgiaLaws()
        "Court Info"->showCourtInfo()
        "Legal Forms"->showLegalForms()
        "Case Analysis"->if(requireSignedIn())showCaseAnalysis()
        "Know Your Rights"->showKnowYourRights()
        "Resources"->showResources()
        "Emergency Help"->showEmergency()
        "Dark Mode"->toggleDarkMode()
        "Settings"->showSettings()
        "Log Out"->logOut()
        else->toast("That menu item is not available.")
    }}
    private fun toggleDarkMode(){val prefs=getSharedPreferences("ga_law_help_ui",MODE_PRIVATE);val next=!prefs.getBoolean("dark_mode",true);prefs.edit().putBoolean("dark_mode",next).apply();toast(if(next)"Dark mode on. Navy and gold screens stay in place." else "Dark mode preference saved. Approved screens stay navy and gold.")}
    private fun showSettings(){val dark=getSharedPreferences("ga_law_help_ui",MODE_PRIVATE).getBoolean("dark_mode",true);val root=page("Settings",HomeDrawer.NOTICE);root.addView(label(if(dark)"Dark mode is on. Approved screens stay navy and gold." else "Dark mode preference is off. Approved screens still use navy and gold.",14f).apply{setTextColor(muted)});addButton(root,if(dark)"Turn dark mode off" else "Turn dark mode on"){toggleDarkMode();showSettings()};addButton(root,"Know Your Rights"){showKnowYourRights()};addButton(root,"Account"){if(requireSignedIn())showAccount()};addButton(root,"Log Out"){logOut()}}
    private fun logOut(){if(api.token==null){toast("You are not signed in. Private cases stay login-only.");startActivity(Intent(this,AuthActivity::class.java));return};thread{api.logout();runOnUiThread{startActivity(Intent(this,AuthActivity::class.java));finish()}}}
    private fun askFromHome(question:String){runTask("Asking GA.LAW.HELP…",{askFromHome(question)}){val result=api.publicAsk(question);val answer=result.optString("answer",result.toString(2));runOnUiThread{AlertDialog.Builder(this).setTitle("GA.LAW.HELP").setMessage(answer).setPositiveButton("AI Help"){_,_->showTalkToMe()}.setNegativeButton("Close",null).show()}}}
    private val talkHistory = StringBuilder()
    private fun showTalkToMe(){val root=page("Talk to Me","Ask a legal question in plain language. Free guest help — no login. Verify deadlines and case-specific advice with qualified Georgia counsel. Do not resist, lie, or destroy evidence.");val question=input("Ask a legal question…",true);val answer=label(talkHistory.toString(),15f);root.addView(question);root.addView(answer);addButton(root,"Ask GA.LAW.HELP"){val q=question.text.toString().trim();if(q.isBlank())return@addButton toast("Enter a question first.");runTask("Working on your question…",{showTalkToMe()}){val reply=TalkToMeController.reply(api,talkHistory,q,"Respond in English.");TalkToMeController.append(talkHistory,reply);runOnUiThread{answer.text=talkHistory.toString();question.setText("")}}}}
    private fun showCases(){if(!requireSignedIn())return; val root=page("My Cases","Manage case files, timelines, evidence and analysis.");addButton(root,"+ Add New Case"){showCreateCase()};val loading=label("Loading cases…",14f).apply{setTextColor(muted)};root.addView(loading);runTask("Loading cases…",{showCases()}){val cases=api.cases();runOnUiThread{root.removeView(loading);if(cases.length()==0)root.addView(label("No cases yet. Tap Add New Case to create one.",14f).apply{setTextColor(muted)});for(i in 0 until cases.length()){val item=cases.optJSONObject(i)?:continue;val id=item.optInt("id");val title=item.optString("title","Case #$id");val county=item.optString("county","");addButton(root,if(county.isBlank())title else "$title  •  $county"){showCase(id)}}}}}
    private fun showCreateCase(){val root=page("Add Case","Create the case file first; evidence and analysis can be added afterward.");val title=input("Case title");val county=input("Georgia county");val stage=input("Stage (pretrial, appeal, etc.)");val narrative=input("What happened?",true);listOf(title,county,stage,narrative).forEach{root.addView(it,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,dp(5),0,dp(5))})};addButton(root,"Save Case"){if(title.text.toString().trim().isBlank())return@addButton toast("Enter a case title.");runTask("Creating case…",{showCreateCase()}){val created=api.createCase(title.text.toString().trim(),county.text.toString().trim(),stage.text.toString().trim(),narrative.text.toString().trim());val id=created.optInt("id");runOnUiThread{if(id>0)showCase(id)else showCases()}}}}
    private fun showCase(caseId:Int){val root=page("Case","Case workspace");root.addView(label("Loading case…",14f).apply{setTextColor(muted)});runTask("Loading case…",{showCase(caseId)}){val detail=api.caseDetail(caseId);runOnUiThread{root.removeViews(2,root.childCount-2);root.addView(label(detail.optString("title","Case #$caseId"),23f,true));val summary=listOf(detail.optString("county"),detail.optString("stage"),detail.optString("narrative")).filter{it.isNotBlank()}.joinToString("\n\n");if(summary.isNotBlank())root.addView(label(summary,14f).apply{setTextColor(muted)});addButton(root,"Case Timeline"){showTimeline(caseId)};addButton(root,"Documents & Evidence"){showCaseDocuments(caseId)};addButton(root,"Innocence & Motion Review"){showInnocenceAnalysis(caseId)};addButton(root,"Case Chat"){showCaseChat(caseId)};addButton(root,"Verified Motion Screen"){showMotionScreen(caseId)};addButton(root,"Run General Case Analysis"){runCaseAnalysis(caseId)};addButton(root,"Why / Explain the Case"){showCaseJson("Why this matters",{api.why(caseId)})};addButton(root,"Red-Team Review"){showCaseJson("Red-Team Review",{api.redTeam(caseId)})};addButton(root,"Second Look"){showCaseJson("Second Look",{api.secondLook(caseId)})}}}}
    private fun showCaseChat(caseId:Int){val root=page("Case Chat","Talk through this case. Answers use your case file, recent messages, and verified Georgia authority only. Confirm deadlines and strategy with qualified Georgia counsel.");val transcript=label("",14f);root.addView(transcript);val history=JSONArray();val message=input("Ask about this case…",true);root.addView(message);addButton(root,"Send"){val text=message.text.toString().trim();if(text.isBlank())return@addButton toast("Enter a question first.");if(text.length>4000)return@addButton toast("Message is too long. Use 4,000 characters or fewer.");message.setText("");transcript.append("You: $text\n\n");runTask("Analyzing your case…",{showCaseChat(caseId)}){val result=api.caseChat(caseId,text,history);val answer=GroundedLegalResult.answer(result).ifBlank{"No grounded case analysis was returned. Add specific facts and try again."};val authorities=GroundedLegalResult.authoritySummary(result);runOnUiThread{history.put(JSONObject().put("role","user").put("content",text));history.put(JSONObject().put("role","assistant").put("content",answer));while(history.length()>20)history.remove(0);transcript.append("GA.LAW.HELP: $answer"+(if(authorities.isNotBlank())"\n\n$authorities" else "")+"\n\n")}}}}
    private fun showTimeline(caseId:Int){val root=page("Case Timeline","Events from first to latest.");runTask("Loading timeline…",{showTimeline(caseId)}){val items=api.timeline(caseId);runOnUiThread{renderJsonArray(root,items,"No timeline events yet.")}}}
    private fun showCaseAnalysis(){if(!requireSignedIn())return; val root=page("Case Analysis","Choose a case, then tell GA.LAW.HELP details that may matter to innocence, reasonable doubt, motions, or post-conviction review.");runTask("Loading cases…",{showCaseAnalysis()}){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("Create a case first.",14f).apply{setTextColor(muted)});for(i in 0 until cases.length()){val item=cases.optJSONObject(i)?:continue;val id=item.optInt("id");addButton(root,item.optString("title","Case #$id")){showInnocenceAnalysis(id)}}}}}
    private fun showInnocenceAnalysis(caseId:Int){val root=page("Innocence & Motion Review","Tell the app what happened, what evidence exists, what seems wrong, and anything that may show innocence or reasonable doubt. The app will look for issues and verified Georgia authority without assuming guilt or innocence.");val facts=input("Add case details: alibi, witnesses, identification, video, DNA, statements, searches, withheld evidence, changed testimony, missing proof, or new evidence…",true).apply{minLines=8};root.addView(facts,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,dp(6),0,dp(8))});root.addView(label("Important: describe facts as accurately as possible. The analysis separates affirmative innocence evidence from reasonable-doubt or insufficiency issues.",13f).apply{setTextColor(muted)});addButton(root,"Analyze Case Details"){val additional=facts.text.toString().trim();runTask("Analyzing case details…",{showInnocenceAnalysis(caseId)}){val result=api.innocenceAnalysis(caseId,additional);runOnUiThread{renderInnocenceResult(root,result,caseId)}}};addButton(root,"Back to Case"){showCase(caseId)}}
    private fun renderInnocenceResult(root:LinearLayout,result:JSONObject,caseId:Int){val review=result.optJSONObject("innocence_review");val motion=result.optJSONObject("motion_and_remedy_review");root.addView(label("Analysis Results",22f,true));if(review!=null){val interpretation=review.optString("interpretation");if(interpretation.isNotBlank())root.addView(label(interpretation,14f).apply{setTextColor(muted)});val signals=review.optJSONArray("issue_signals")?:JSONArray();root.addView(label("Potential Issues",18f,true));renderJsonArray(root,signals,"No specific innocence/doubt signal was identified from the supplied details. Add more facts or records rather than treating this as a negative conclusion.");val questions=review.optJSONArray("follow_up_questions")?:JSONArray();root.addView(label("Questions to Investigate",18f,true));renderJsonArray(root,questions,"No additional questions generated.")};if(motion!=null){root.addView(label("Motions / Remedies to Research",18f,true));val analysis=motion.optString("analysis");if(analysis.isNotBlank())root.addView(label(analysis,14f));val coverage=motion.optJSONObject("authority_coverage");if(coverage!=null)root.addView(label("Verified-authority coverage\n${coverage.toString(2)}",13f).apply{setTextColor(muted)})};root.addView(label(result.optString("notice","Verify facts, current authority, deadlines, and filing requirements before relying on this analysis."),12f).apply{setTextColor(muted)});addButton(root,"Analyze More Details"){showInnocenceAnalysis(caseId)};addButton(root,"Back to Case"){showCase(caseId)}}
    private fun runCaseAnalysis(caseId:Int){val root=page("Case Analysis","Running a fresh general case review.");root.addView(label("Analyzing…",14f).apply{setTextColor(muted)});runTask("Running case analysis…",{runCaseAnalysis(caseId)}){val result=api.runAnalysis(caseId);runOnUiThread{root.removeViews(2,root.childCount-2);root.addView(label(pretty(result),14f));addButton(root,"Innocence & Motion Review"){showInnocenceAnalysis(caseId)};addButton(root,"Back to Case"){showCase(caseId)}}}}
    private fun showMotionScreen(caseId:Int){val root=page("Verified Motion Screen","Login-only screening for this saved case. This is not a filing and does not certify current Georgia law.");val facts=input("Additional facts for motion screening",true);root.addView(facts);addButton(root,"Run motion screen"){runTask("Screening motions…",{showMotionScreen(caseId)}){val result=api.motionScreen(caseId, facts.text.toString().trim());runOnUiThread{while(root.childCount>4)root.removeViewAt(root.childCount-1);val analysis=result.optString("analysis").ifBlank{result.optString("answer")}.ifBlank{pretty(result)};root.addView(label(analysis,14f));root.addView(label("Do not treat unverified citations as current Georgia law. Confirm the official source, deadlines, and procedural posture before relying on this screen.",13f).apply{setTextColor(muted)})}}}}
    private fun showCaseJson(title:String,loader:()->JSONObject){val root=page(title,"Case review output");runTask("Loading…",{showHome()}){val result=loader();runOnUiThread{root.addView(label(pretty(result),14f))}}}
    private fun showGeorgiaLaws(){startActivity(Intent(this, GeorgiaLawsActivity::class.java))}
    private fun showCourtInfo(){val root=page("Court Info","Official Georgia court information and self-help resources.");addButton(root,"Georgia Courts"){openUrl("https://georgiacourts.gov/")};addButton(root,"Find a Court"){openUrl("https://georgiacourts.gov/find-a-court/")};root.addView(label("Court dates, filing rules and deadlines can vary by court. Confirm case-specific requirements with the court or qualified counsel.",14f).apply{setTextColor(muted)})}
    private fun showLegalForms(){val root=page("Legal Forms","Start with official court and legal-aid sources when possible.");addButton(root,"Georgia Courts Self-Help"){openUrl("https://georgiacourts.gov/a2j/")};addButton(root,"Georgia Legal Aid"){openUrl("https://www.georgialegalaid.org/")};root.addView(label("Before filing, confirm that a form is current and accepted by the court handling your case.",14f).apply{setTextColor(muted)})}
    private fun showLegalTools(){val root=page("Legal Tools","Public guides stay open. Case analysis and saved cases stay login-only.");addButton(root,"Case Analysis"){showCaseAnalysis()};addButton(root,"Georgia Laws"){showGeorgiaLaws()};addButton(root,"Legal Forms"){showLegalForms()};addButton(root,"Court Info"){showCourtInfo()};addButton(root,"Know Your Rights"){showKnowYourRights()}}
    private fun showKnowYourRights(){val root=page("Know Your Rights","Plain-language starting points for common encounters.");root.addView(label("Police encounter\n• Stay calm and do not physically resist.\n• You may clearly state that you wish to remain silent.\n• You may ask whether you are free to leave.\n• You can clearly state that you do not consent to a search.\n• If you are in custody and being questioned, request a lawyer.\n\nThese are general information points; facts and legal rules can change the answer.",15f));addButton(root,"Ask GA.LAW.HELP about my situation"){showTalkToMe()}}
    private fun showResources(){val root=page("Resources","Georgia courts, legal aid and assistance resources.");addButton(root,"Georgia Legal Aid"){openUrl("https://www.georgialegalaid.org/")};addButton(root,"Georgia Courts"){openUrl("https://georgiacourts.gov/")};addButton(root,"Georgia Public Defender Council"){openUrl("https://gapubdef.org/")};addButton(root,"988 Crisis & Suicide Lifeline"){openUrl("https://988lifeline.org/")}}
    private fun showEmergency(){val root=page("Emergency Help","Immediate safety and crisis resources. This is not a substitute for 911.");root.addView(label("If someone is in immediate danger, contact emergency services. GA.LAW.HELP is not an emergency-response service.",15f));addButton(root,"Call / Dial 911"){startActivity(Intent(Intent.ACTION_DIAL,Uri.parse("tel:911")))};addButton(root,"Call / Dial 988"){startActivity(Intent(Intent.ACTION_DIAL,Uri.parse("tel:988")))};addButton(root,"Georgia Public Defender Council"){openUrl("https://gapubdef.org/")};addButton(root,"Know Your Rights"){showKnowYourRights()}}
    private fun showDocuments(){if(!requireSignedIn())return; val root=page("Documents","Choose a case to view or upload evidence and case files.");runTask("Loading cases…",{showDocuments()}){val cases=api.cases();runOnUiThread{if(cases.length()==0)root.addView(label("Create a case before uploading case documents.",14f).apply{setTextColor(muted)});for(i in 0 until cases.length()){val item=cases.optJSONObject(i)?:continue;val id=item.optInt("id");addButton(root,item.optString("title","Case #$id")){showCaseDocuments(id)}}}}}
    private fun showCaseDocuments(caseId:Int){val root=page("Documents","Evidence and files attached to this case.");addButton(root,"+ Upload Document"){pendingUploadCaseId=caseId;pickDocument.launch(arrayOf("application/pdf","image/*","text/*","application/msword","application/vnd.openxmlformats-officedocument.wordprocessingml.document"))};runTask("Loading documents…",{showCaseDocuments(caseId)}){val items=api.evidence(caseId);runOnUiThread{renderJsonArray(root,items,"No documents uploaded yet.")}}}
    private fun showAccount(){if(!requireSignedIn())return; val root=page("Account","Profile, membership and secure sign-out.");val loading=label("Loading account…",14f).apply{setTextColor(muted)};root.addView(loading);runTask("Loading account…",{showAccount()}){val me=api.me();val billing=runCatching{api.billingStatus()}.getOrNull();runOnUiThread{root.removeView(loading);root.addView(label(me.optString("email","Signed in"),19f,true));val role=me.optString("role");if(role.isNotBlank())root.addView(label("Role: $role",14f).apply{setTextColor(muted)});if(billing!=null)root.addView(label("Membership: ${billing.optString("status",billing.optString("plan","available"))}",14f).apply{setTextColor(muted)});addButton(root,"Manage Membership"){openCheckout()};addButton(root,"Sign Out"){thread{api.logout();runOnUiThread{startActivity(Intent(this,AuthActivity::class.java));finish()}}}}}}
    private fun openCheckout(){runTask("Opening membership…",{showAccount()}){val checkout=api.createCheckout("monthly");val url=checkout.optString("url",checkout.optString("checkout_url"));runOnUiThread{if(url.startsWith("http"))openUrl(url)else toast("Membership checkout is not available right now.")}}}
    private fun renderJsonArray(root:LinearLayout,items:JSONArray,emptyMessage:String){if(items.length()==0){root.addView(label(emptyMessage,14f).apply{setTextColor(muted)});return};for(i in 0 until items.length()){val item=items.opt(i);val text=when(item){is JSONObject->pretty(item);else->item?.toString().orEmpty()};root.addView(label(text,14f).apply{setPadding(dp(12),dp(10),dp(12),dp(10));background=rounded(panel,Color.rgb(31,75,105),1,12)},LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,dp(5),0,dp(5))})}}
    private fun pretty(obj:JSONObject):String{val preferred=listOf("title","citation","summary","analysis","answer","detail","description","status","county","stage","issue","kind","note");val lines=preferred.mapNotNull{key->obj.optString(key).takeIf{it.isNotBlank()}?.let{"$key: $it"}};return if(lines.isNotEmpty())lines.joinToString("\n\n")else obj.toString(2)}
    private fun openUrl(url:String){runCatching{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}.onFailure{toast("No browser is available for this link.")}}
    private fun runTask(message:String,retry:()->Unit,work:()->Unit){toast(message);thread{try{work()}catch(e:Exception){runOnUiThread{showError(e.message?:"Something went wrong. Please try again.",retry)}}}}
    private fun showError(message:String,retry:()->Unit){val root=page("Couldn’t complete that","Your app is still usable. You can retry or return Home.");root.addView(label(message,15f));addButton(root,"Retry"){retry()};addButton(root,"Home"){showHome()}}
    private fun toast(message:String)=Toast.makeText(this,message,Toast.LENGTH_SHORT).show()
}